from taf.rfrl.bts.connections import device_aliases


def login_logout(web_fun):
    @wraps(web_fun)
    def wrapper(self, *args, **kwargs):
        passed_args = getcallargs(web_fun, self, *args, **kwargs)
        bts_id_arg_name = _get_bts_id_arg_name(passed_args=passed_args.keys())
        passed_args[bts_id_arg_name] = int(passed_args[bts_id_arg_name])

        bts_id = passed_args[bts_id_arg_name]
        requests.packages.urllib3.disable_warnings(category=InsecureRequestWarning)

        self.connect(bts_id=bts_id)
        try:
            result = web_fun(**passed_args)
            return result
        finally:
            self.disconnect(bts_id=bts_id)

    return wrapper


def login_logout_GUI(web_fun):
    @wraps(web_fun)
    def wrapper(self, *args, **kwargs):
        passed_args = getcallargs(web_fun, self, *args, **kwargs)
        bts_id_arg_name = _get_bts_id_arg_name(passed_args=passed_args.keys())
        passed_args[bts_id_arg_name] = int(passed_args[bts_id_arg_name])

        bts_id = passed_args[bts_id_arg_name]

        if self.gui_coam_cu is None:
            self.login_gui(bts_id=bts_id)
        elif self._gui_coam_cu_connection_name == device_aliases.gui_gnb_cu.format(bts_id):
            try:
                result = web_fun(**passed_args)
                return result
            except Exception as ex:
                logging.warning("Cannot call method {}. Caught exception: {}".format(web_fun.__name__, repr(ex)))
                logging.warning("Try to login again")
                self._login_gui(bts_id=bts_id)
        else:
            self.logout_gui()
            self.login_gui(bts_id=bts_id)

        return web_fun(**passed_args)

    return wrapper


class GenericCu(object):
    """CU(Centralized Unit) keywords for gNB"""

    cu = cuadmin()
    gui_coam_cu = selenium_cu()

    def __init__(self, bts_type='GNB'):
        """
        Constructor of GenericBts class.

        :param bts_type: GNB|ENB
        """

        self.bts_type = bts_type

        self.gui_coam_cu = None
        self._gui_coam_cu_connection_name = None

    def __del__(self):
        if self.gui_coam_cu:
            self.logout_gui()

    def connect(self, timeout=None, bts_id=0):
        """
        Connect to gNB CU

        :param Union[int,str] timeout: (optional) Timeout for the operation.
        :return: None
        """
        logging.debug("[CU] Connecting to {}".format(device_aliases.rest_gnb_cu.format(bts_id)))
        credentials = tl_config.get_web_credentials_for_cu(bts_id, self.bts_type)
        self.cu.connect_to(host=credentials['ip'],
                           port='',
                           username=credentials['username'],
                           password=credentials['password'],
                           cu_version="cuoam_21b",
                           secure=True,
                           timeout=timeout
                           )

    def disconnect(self, bts_id=0):
        """
        Disconnect from gNB CU

        :return: None
        """
        try:
            logging.debug("[CU] Disconnecting from {}".format(device_aliases.rest_gnb_cu.format(bts_id)))
            self.cu.disconnect()
        except MaxRetryError:
            logging.debug("[CU] Already disconnected")
            time.sleep(30)

    def login_gui(self, bts_id=0):
        """
        Login to BTS via GUI

        :return: None
        """
        selenium_logs = os.path.join(get_builtin_value("OUTPUTDIR"), 'selenium_logs')

        self.gui_coam_cu = selenium_cu()

        self._gui_coam_cu_connection_name = device_aliases.gui_gnb_cu.format(bts_id)

        self.gui_coam_cu.enable_virtual_display()

        self.gui_coam_cu.download_dir = os.path.join(selenium_logs, 'download')
        self._login_gui(bts_id=bts_id)

    def _login_gui(self, bts_id=0):
        credentials = tl_config.get_web_credentials_for_cu(bts_id, self.bts_type)

        self.gui_coam_cu.enable_virtual_display()
        self.gui_coam_cu.login(url='https://{}/'.format(credentials['ip']),
                               username=credentials['username'],
                               password=credentials['password'],
                               browser='Chrome',
                               version=self._get_proper_coam_selenium_version(bts_id=bts_id))

    @login_logout
    def _get_proper_coam_selenium_version(self, bts_id=0):
        version = None
        release_number = None
        cu_software = None
        supported_versions = ["21B", "22R1", "22R2"]
        current_trunk_releases = ['22R3']

        try:
            cu_software = self.cu.get_active_software_version()
        except ApiException:
            MolerTest.info("Cannot get active software version via API")
            version = self._get_sw_version_from_system_file(bts_id=bts_id)
        if cu_software:
            logging.debug("[CU] Software version: {}".format(cu_software))
            # 5G20B_10.1100.1322, 5G22R1_0.200.1452
            match = re.search(r'5G(\d+(?:([A-C])|(R\d+)))_', cu_software)
            if match:
                release_number = match.group(1)
                logging.debug("[CU] Release number: {}".format(release_number))
            if release_number:
                if release_number in supported_versions:
                    version = release_number
                elif release_number in current_trunk_releases:
                    version = supported_versions[-1]

        logging.debug("Selected selenium version: {}".format(version))
        return version

    def logout_gui(self):
        """
        Logout from BTS via GUI

        :return: None
        """
        for x in range(5):
            try:
                self.gui_coam_cu.logout()
                break
            except ElementClickInterceptedException:
                time.sleep(5)
        self.gui_coam_cu.disable_virtual_display()
        self.gui_coam_cu = None

    def adjust_dist_name(self, dist_name, bts_id=0, du_id=0):
        """
        Adjust mrbts_id and global bts id (nrbts_id or lnbts_id) in given distName.

        :param dist_name:               distName in format e.g. MRBTS-{}/NRBTS-{}/NRCELL-1
        :type dist_name:                str
        :param bts_id:                  enb_id or gnb_id, related to test line configuration, default set to 0
        :type bts_id:                   int or str
        :param du_id: DU id(Distributed Unit) - id related to Test Line configuration - gnb.dus[]
        :type du_id:                    int or str
        :return: distName with proper values
        """
        mrbts_id = tl_config.get_bts_instance_id(bts_id=bts_id, du_id=du_id)
        global_bts_id = tl_config.get_global_bts_id(bts_id=bts_id, du_id=du_id)
        return dist_name.format(mrbts_id, global_bts_id)

    def _delete_plan_if_needed_via_gui(self, plan_name):
        """
        Method attempts to remove existing plan template.

        :param plan_name:   Name of the plan to remove
        :return:            None
        """
        plans = self.gui_coam_cu.get_all_plans()
        plan_list = list(plans["Planned configurations:"].values())
        logging.debug("Found plan list: {}".format(plan_list))
        for i in plan_list:
            if not isinstance(i, list):
                plan_list.remove(i)
        logging.debug("Filtered plan list: {}".format(plan_list))
        if not plan_list[0]:
            return
        plan_list = list(itertools.chain(*plan_list))
        if plan_name in plan_list:
            self.gui_coam_cu.choose_plan(plan_name=plan_name)
            self.gui_coam_cu.delete_plan()

    @login_logout_GUI
    def _create_plan_if_needed(self, plan_name="CURRENT_PLAN", new_plan_name="NEW_PLAN", bts_id=0):
        plans = self.gui_coam_cu.get_all_plans()
        plan_list = list(plans["Planned configurations:"].values())
        for i in plan_list:
            if not isinstance(i, list):
                plan_list.remove(i)
        if not plan_list[0]:
            self.gui_coam_cu.create_plan(choose_plan=plan_name,
                                         plan_name=new_plan_name)
        else:
            plan_list = list(itertools.chain(*plan_list))
            if new_plan_name not in plan_list:
                self.gui_coam_cu.create_plan(choose_plan=plan_name,
                                             plan_name=new_plan_name)

    @login_logout_GUI
    def _create_delta_plan_via_GUI_if_needed(self, plan_name="NEW_DELTA_PLAN", bts_id=0):
        """
        Create a delta plan if needed via GUI
        :param plan_name:       Name for new delta plan
        :param bts_id:          BTS id - related to Test Line configuration
        """
        plans = self.gui_coam_cu.get_all_plans()
        plan_list = plans["Delta configurations:"]["plan"]
        if not plan_list:
            self.gui_coam_cu.create_delta_plan(plan_name=plan_name)
        else:
            if plan_name not in plan_list:
                self.gui_coam_cu.create_delta_plan(plan_name=plan_name)

    @tl_config.load_moler_configuration_from_tl()
    def _get_sw_version_from_system_file(self, bts_id=0):
        """
        Get CU sw version from system file located at OAM VM.
        :param bts_id:         BTS id - related to Test Line configuration
        """
        # /var/swm/cbtsBD_5G22R1_0.200.1931.xml
        version_re = re.compile(r"cbtsBD_(?:5G)?(?P<version>\w+)_[\d\.]+\.xml$")
        gnb = DeviceFactory.get_device(format(device_aliases.ssh_gnb_cu.format(bts_id)))
        gnb.goto_state('OAM')
        files = gnb.get_cmd(cmd_name='ls', cmd_params={'path': '/var/swm/*.xml'})()
        for f in files['files'].keys():
            match = re.search(version_re, f)
            if match:
                return match.group('version')
